local Fluent = loadstring(game:HttpGet("https://github.com"))() local Window = Fluent:CreateWindow({Title = "Men Hub | Blox Fruits", SubTitle = "by Men", TabWidth = 160, Size = UDim2.fromOffset(580, 460), Acrylic = true, Theme = "Dark", MinimizeKey = Enum.KeyCode.RightControl}) local Tabs = {Main = Window:AddTab({ Title = "Фарм и Функции", Icon = "home" }), Race = Window:AddTab({ Title = "Авто Раса", Icon = "user" })} local Player = game:GetService("Players").LocalPlayer local VirtualUser = game:GetService("VirtualUser") _G.AutoClick = true _G.AutoHaki = true spawn(function() while _G.AutoClick do task.wait(0.01) VirtualUser:CaptureController() VirtualUser:Button1Down(Vector2.new(0,0), workspace.CurrentCamera.CFrame) end end) spawn(function() while _G.AutoHaki do task.wait(2) if not Player.Character:FindFirstChild("HasBuso") then game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("Buso") end end end) Fluent:Notify({ Title = "Men Hub Активен", Content = "Авто-клик и Хаки включены!", Duration = 5 }) Tabs.Main:AddToggle("AutoClickToggle", { Title = "Авто-Клик", Default = true, Callback = function(Value) _G.AutoClick = Value end }) Tabs.Main:AddToggle("AutoHakiToggle", { Title = "Авто-Хаки", Default = true, Callback = function(Value) _G.AutoHaki = Value end }) _G.RaceV2 = false Tabs.Race:AddToggle("RaceV2Toggle", { Title = "Авто Выполнение Расы V2", Default = false, Callback = function(Value) _G.RaceV2 = Value spawn(function() while _G.RaceV2 do task.wait(1) local Alchemist = workspace:FindFirstChild("Alchemist") or (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Alchemist")) if Alchemist and Player.Character:FindFirstChild("HumanoidRootPart") then Player.Character.HumanoidRootPart.CFrame = Alchemist.HumanoidRootPart.CFrame * CFrame.new(0,0,3) if Alchemist:FindFirstChildOfClass("ClickDetector") then fireclickdetector(Alchemist:FindFirstChildOfClass("ClickDetector")) end end for _, v in pairs(workspace:GetChildren()) do if v.Name == "Flower1" or v.Name == "Flower2" or v.Name == "Flower3" then if v:FindFirstChild("TouchInterest") and Player.Character:FindFirstChild("HumanoidRootPart") then Player.Character.HumanoidRootPart.CFrame = v.CFrame task.wait(0.5) end end end end end) end }) _G.RaceV3 = false Tabs.Race:AddToggle("RaceV3Toggle", { Title = "Авто Выполнение Расы V3", Default = false, Callback = function(Value) _G.RaceV3 = Value spawn(function() while _G.RaceV3 do task.wait(1) local Arowe = workspace:FindFirstChild("Arowe") or (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Arowe")) if Arowe and Player.Character:FindFirstChild("HumanoidRootPart") then Player.Character.HumanoidRootPart.CFrame = Arowe.HumanoidRootPart.CFrame * CFrame.new(0,0,3) if Arowe:FindFirstChildOfClass("ClickDetector") then fireclickdetector(Arowe:FindFirstChildOfClass("ClickDetector")) end end end end) end }) Window:SelectTab(1)
